window.__FORMULAS__ = {"chapters":[{"id":1,"title_zh":"水量计算","formulas":[{"code":"F-1.2","name":"综合生活污水量（平均日）","expr":"Q_d = \\dfrac{q \\cdot N}{86400}\\ (\\mathrm{L/s})\\ \\text{或}\\ \\ Q_d = \\dfrac{q \\cdot N}{1000}\\ (\\mathrm{m^3/d})","symbols":[{"s":"q","d":"综合生活污水定额","u":"L/(人·d)"},{"s":"N","d":"设计人口","u":"人"},{"s":"Q_d","d":"平均日污水量","u":"L/s 或 m³/d"}],"range":"污水定额按用水定额 90%；用水定额 110～400 L/(人·d)","note":"GB 50014-2021 §4.1.14；不完善地区可取 80%～90%"},{"code":"F-1.3","name":"变化系数定义","expr":"K_d = \\dfrac{Q_{max,d}}{Q_{avg,d}};\\quad K_h = \\dfrac{Q_{max,h}}{Q_{avg,h}};\\quad K_z = K_d \\cdot K_h","symbols":[{"s":"K_d","d":"日变化系数","u":"—"},{"s":"K_h","d":"时变化系数","u":"—"},{"s":"K_z","d":"总变化系数","u":"—"}],"range":"K_d 1.1～1.5；K_h 1.3～1.6","note":"GB 50014-2021 表值即 K_z 口径"},{"code":"F-1.4","name":"综合生活污水量变化系数表（GB 50014-2021 表 4.1.15）","expr":"Q_{avg}=5,15,40,70,100,200,500,\\geq 1000\\ \\mathrm{L/s}\\ \\Rightarrow\\ K_z=2.7,2.4,2.1,2.0,1.9,1.8,1.6,1.5","symbols":[{"s":"Q_avg","d":"平均日流量","u":"L/s"},{"s":"K_z","d":"变化系数（内插）","u":"—"}],"range":"8 档，中间值内插","note":"无实测资料的新建项目查表；较 2006 版上调约 15%"},{"code":"F-1.6","name":"设计流量分级","expr":"Q_{max,h} = K_z \\cdot Q_{avg};\\quad Q_{max,d} = K_d \\cdot Q_{avg}","symbols":[{"s":"Q_avg","d":"平均日平均时流量","u":"m³/d"},{"s":"Q_max,h","d":"最高日最高时流量","u":"m³/d"}],"range":"生化池按平均日；格栅/沉砂/二沉池按最高时","note":"各构筑物设计流量口径不同"},{"code":"F-1.7","name":"旱季设计流量（分流制）","expr":"Q_{dr} = K \\cdot Q_d + K' \\cdot Q_m + Q_u","symbols":[{"s":"Q_d","d":"设计综合生活污水量","u":"L/s"},{"s":"Q_m","d":"设计工业废水量","u":"L/s"},{"s":"Q_u","d":"入渗地下水量","u":"L/s"}],"range":"Q_u 按旱流 5%～15% 估算（无实测时）","note":"GB 50014-2021 式 (4.1.13)"},{"code":"F-1.9","name":"截流式合流制设计流量与雨水量","expr":"Q_{截} = (n_0+1)\\, Q_{dr};\\quad Q_s = q \\cdot \\psi \\cdot F;\\quad q = \\dfrac{167 A_1 (1+C\\lg P)}{(t+b)^n}","symbols":[{"s":"n_0","d":"截流倍数","u":"—"},{"s":"q","d":"设计暴雨强度","u":"L/(s·hm²)"},{"s":"ψ","d":"综合径流系数","u":"—"},{"s":"F","d":"汇水面积","u":"hm²"}],"range":"n₀=2～5；ψ 屋面 0.8～0.9、绿地 0.10～0.20","note":"GB 50014-2021 §4.1.24；汇水面积 ≤2 km² 用推理公式法"}]},{"id":2,"title_zh":"水质与负荷","formulas":[{"code":"F-2.1","name":"污染物负荷换算","expr":"L = \\dfrac{Q \\cdot C}{1000}","symbols":[{"s":"Q","d":"流量","u":"m³/d"},{"s":"C","d":"浓度","u":"mg/L"},{"s":"L","d":"负荷","u":"kg/d"}],"range":"全流程通用","note":"峰值负荷按 Q_max,h 校核"},{"code":"F-2.2","name":"人均当量法设计水质","expr":"C = \\dfrac{a}{q} \\times 1000","symbols":[{"s":"a","d":"人均污染物当量","u":"g/(人·d)"},{"s":"q","d":"污水定额","u":"L/(人·d)"},{"s":"C","d":"浓度","u":"mg/L"}],"range":"a(BOD₅) 25～50、a(SS) 40～65、a(TN) 5～11、a(TP) 0.7～1.4","note":"无实测资料时按此计算生活污水水质"},{"code":"F-2.4","name":"混合水质加权","expr":"C_{mix} = \\dfrac{\\sum Q_i C_i}{\\sum Q_i}","symbols":[{"s":"Q_i","d":"各股流量","u":"m³/d"},{"s":"C_i","d":"各股浓度","u":"mg/L"}],"range":"多股进水合并处理","note":"pH、水温不可简单加权"},{"code":"F-2.5","name":"可生化性判据","expr":"R_{B/C} = \\dfrac{BOD_5}{COD}","symbols":[{"s":"BOD_5","d":"五日生化需氧量","u":"mg/L"},{"s":"COD","d":"化学需氧量","u":"mg/L"}],"range":"≥0.45 易生化；0.30～0.45 可生化；<0.25 不宜直接生化","note":"结合 BOD₅/TN、BOD₅/TP 综合判断"},{"code":"F-2.6","name":"BOD 动力学与 BODu 换算","expr":"BOD_t = L_0 \\left(1 - e^{-k_1 t}\\right);\\quad k_{1,T} = k_{1,20}\\cdot 1.047^{(T-20)}","symbols":[{"s":"L_0","d":"最终生化需氧量 BODu","u":"mg/L"},{"s":"k_1","d":"耗氧速率常数（以 e 为底）","u":"d⁻¹"}],"range":"k₁(20℃)=0.15～0.40（常用 0.23）；BODu≈1.47×BOD₅","note":"以 10 为底 k₁₀=0.10 等价；引用文献先确认对数底数"},{"code":"F-2.8","name":"营养与碳源平衡判据","expr":"BOD_5:N:P = 100:5:1;\\quad \\dfrac{BOD_5}{TN} \\geq 4;\\quad \\dfrac{BOD_5}{TP} \\geq 17;\\quad \\dfrac{ALK}{NH_3\\text{-}N} \\geq 7.14","symbols":[{"s":"ALK","d":"进水碱度（以 CaCO₃ 计）","u":"mg/L"},{"s":"TN","d":"总氮","u":"mg/L"},{"s":"TP","d":"总磷","u":"mg/L"}],"range":"不满足时补碳源或碱度","note":"HJ 标准判据（已复核标准原文）"}]},{"id":3,"title_zh":"活性污泥动力学","formulas":[{"code":"F-3.4","name":"表观产率（实测产泥系数）","expr":"Y_{obs} = \\dfrac{Y}{1 + K_d \\cdot \\theta_c}","symbols":[{"s":"Y","d":"产率系数","u":"kgVSS/kgBOD₅"},{"s":"K_d","d":"内源衰减系数","u":"d⁻¹"},{"s":"θ_c","d":"污泥龄","u":"d"}],"range":"θ_c=5～15 d 时约 0.3～0.4；市政厂统计 0.4～0.6","note":"直接用于剩余污泥量估算（F-9.1）"},{"code":"F-3.5","name":"食微比 F/M","expr":"\\dfrac{F}{M} = \\dfrac{Q \\cdot S_0}{V \\cdot X}","symbols":[{"s":"Q","d":"进水流量","u":"m³/d"},{"s":"S_0","d":"进水 BOD₅","u":"kg/m³"},{"s":"V","d":"曝气池容积","u":"m³"},{"s":"X","d":"MLSS","u":"kg/m³"}],"range":"传统 0.2～0.4；氧化沟 0.03～0.10 kgBOD/(kgMLSS·d)","note":"S₀ 与 X 取同一浓度单位"},{"code":"F-3.6","name":"污泥龄（SRT）定义式","expr":"\\theta_c = \\dfrac{V \\cdot X}{Q_w \\cdot X_r + Q_e \\cdot X_e}","symbols":[{"s":"Q_w","d":"排泥量","u":"m³/d"},{"s":"X_r","d":"回流污泥浓度","u":"kg/m³"},{"s":"Q_e、X_e","d":"出水流量与出水 SS","u":"m³/d；kg/m³"}],"range":"传统 5～15 d；硝化系统 10～20 d","note":"X_e 很小时简化为 VX/(Q_w·X_r)"},{"code":"F-3.9","name":"污泥回流比与曝气池浓度","expr":"X = \\dfrac{R}{1+R} \\cdot X_r","symbols":[{"s":"R","d":"污泥回流比","u":"—"},{"s":"X_r","d":"回流污泥浓度","u":"kg/m³"},{"s":"X","d":"混合液 MLSS","u":"kg/m³"}],"range":"R=25%～100%（氧化沟 50%～150%）","note":"联合 SVI 与 X_r 确定"},{"code":"F-3.10","name":"SVI 与回流污泥浓度","expr":"SVI = \\dfrac{SV_{30}(\\%) \\times 10}{MLSS(\\mathrm{g/L})};\\quad X_r = \\dfrac{10^6}{SVI} \\cdot k_r","symbols":[{"s":"SV_30","d":"30 min 沉降比","u":"%"},{"s":"MLSS","d":"混合液污泥浓度","u":"g/L"},{"s":"k_r","d":"系数","u":"1.0～1.2"}],"range":"SVI 50～150 正常；>200 膨胀","note":"SVI=100 时 X_r≈10～12 g/L"},{"code":"F-3.11","name":"曝气池容积（负荷法）","expr":"V = \\dfrac{Q \\cdot S_0}{L_s \\cdot X};\\quad V = \\dfrac{Q \\cdot S_0}{L_v}","symbols":[{"s":"L_s","d":"BOD 污泥负荷","u":"kgBOD₅/(kgMLSS·d)"},{"s":"L_v","d":"容积负荷","u":"kgBOD₅/(m³·d)"}],"range":"L_s 传统 0.2～0.4、氧化沟 0.05～0.15","note":"S₀、X 以 kg/m³ 计（mg/L×10⁻³）"},{"code":"F-3.12","name":"曝气池容积（污泥龄法）与出水基质","expr":"V = \\dfrac{\\theta_c \\cdot Q \\cdot Y (S_0 - S_e)}{X (1 + K_d \\theta_c)};\\quad S_e = \\dfrac{K_s (1 + K_d \\theta_c)}{\\theta_c (Yk - K_d) - 1}","symbols":[{"s":"k","d":"最大比基质利用速率 μ_max/Y","u":"d⁻¹"},{"s":"K_s","d":"半饱和常数","u":"mg/L"}],"range":"硝化脱氮工艺优先按 SRT 法","note":"Lawrence-McCarty 完全混合模型"},{"code":"F-3.13","name":"动力学参数温度修正","expr":"\\mu_T = \\mu_{20} \\cdot \\theta_T^{(T-20)}","symbols":[{"s":"θ_T","d":"温度系数","u":"—"}],"range":"异养菌 1.04～1.07；硝化菌 1.08～1.123","note":"冬季最低水温为控制工况"}]},{"id":4,"title_zh":"停留时间","formulas":[{"code":"F-4.1","name":"水力停留时间（HRT）","expr":"\\theta = \\dfrac{V}{Q}","symbols":[{"s":"V","d":"池容","u":"m³"},{"s":"Q","d":"流量","u":"m³/d"}],"range":"曝气池 4～8 h（传统）；缺氧池 1～3 h；二沉池 1.5～4 h","note":"生化池按平均日、沉淀池按最高时口径"},{"code":"F-4.2","name":"SRT 与 HRT 关系","expr":"\\dfrac{\\theta_c}{\\theta} = \\dfrac{Q \\cdot X}{Q_w X_r + Q_e X_e}","symbols":[{"s":"θ_c","d":"污泥龄","u":"d"},{"s":"θ","d":"水力停留时间","u":"d"}],"range":"传统法 θ_c/θ ≈ 10～20","note":"回流使泥龄远长于水龄；MBR 完全解耦"},{"code":"F-4.3","name":"理想反应器出水浓度（一级反应）","expr":"C_e = C_0 e^{-k\\theta}\\ \\text{（推流）};\\quad C_e = \\dfrac{C_0}{1+k\\theta}\\ \\text{（完全混合）}","symbols":[{"s":"C_0、C_e","d":"进出水浓度","u":"mg/L"},{"s":"k","d":"一级反应速率","u":"d⁻¹"}],"range":"消毒灭活、BOD 衰减近似","note":"相同去除率下推流容积小于完全混合"},{"code":"F-4.4","name":"停留时间分布（RTD）","expr":"E(t) = \\dfrac{1}{\\theta} e^{-t/\\theta};\\quad E(\\Theta) = \\dfrac{N(N\\Theta)^{N-1}}{(N-1)!} e^{-N\\Theta}","symbols":[{"s":"N","d":"等效串联池数","u":"—"},{"s":"Θ","d":"无量纲时间 t/θ","u":"—"}],"range":"廊道式曝气池 N=3～8；接触池 T₁₀/θ≥0.6","note":"示踪试验实测 T₁₀ 用于 CT 计算"},{"code":"F-4.6","name":"沉淀池停留时间与表面负荷","expr":"t = \\dfrac{V}{Q} = \\dfrac{H}{q}","symbols":[{"s":"H","d":"有效水深","u":"m"},{"s":"q","d":"表面负荷","u":"m/h"}],"range":"H=3 m、q=1.0 m/h 时 t=3 h","note":"加深池容不改变理论去除率（Hazen 理论）"}]},{"id":5,"title_zh":"耗氧量与曝气","formulas":[{"code":"F-5.1","name":"碳氧化需氧量","expr":"O_{2,c} = a \\cdot Q(S_0 - S_e) \\times 10^{-3} - c \\cdot \\Delta X_v","symbols":[{"s":"a","d":"碳氧化氧当量（BODu/BOD₅）","u":"1.47"},{"s":"c","d":"细胞氧化当量","u":"1.42 kgO₂/kgVSS"},{"s":"ΔX_v","d":"挥发性剩余污泥产量","u":"kgVSS/d"}],"range":"Q 以 m³/d、浓度以 mg/L 计","note":"GB 50014-2021 需氧量计算式"},{"code":"F-5.2","name":"硝化需氧量","expr":"O_{2,n} = 4.57 \\times \\left[ 0.001 Q(N_k - N_{ke}) - 0.12 \\Delta X_v \\right]","symbols":[{"s":"4.57","d":"硝化氧当量（64/14）","u":"kgO₂/kgNH₃-N"},{"s":"N_k、N_ke","d":"进出水凯氏氮","u":"mg/L"},{"s":"0.12","d":"细胞含氮率","u":"kgN/kgVSS"}],"range":"约占总需氧量 30%～50%","note":"化学计量复核无误"},{"code":"F-5.3","name":"反硝化回收氧","expr":"O_{2,d} = 2.86 \\times \\left[ 0.001 Q(N_t - N_{ke} - N_{oe}) - 0.12 \\Delta X_v \\right]","symbols":[{"s":"2.86","d":"硝酸盐氧当量（80/28）","u":"kgO₂/kgNO₃-N"},{"s":"N_t","d":"进水总氮","u":"mg/L"},{"s":"N_oe","d":"出水硝态氮","u":"mg/L"}],"range":"在设计总需氧量中扣减","note":"GB 50014-2021 以 0.62b 表达（≈2.83）"},{"code":"F-5.4","name":"总需氧量（AOR）汇总式","expr":"O_2 = 0.001aQ(S_o-S_e) - c\\Delta X_v + b\\left[0.001Q(N_k-N_{ke})-0.12\\Delta X_v\\right] - 0.62b\\left[0.001Q(N_t-N_{ke}-N_{oe})-0.12\\Delta X_v\\right]","symbols":[{"s":"a、b、c","d":"氧当量系数","u":"1.47 / 4.57 / 1.42"}],"range":"硝化脱氮全流程 1.3～1.8 kgO₂/kgBOD₅ 去除","note":"峰值按 K_h 放大 1.3～1.6 决定风机配置"},{"code":"F-5.5","name":"标准氧转移量（SOR）换算","expr":"SOR = \\dfrac{AOR \\cdot C_{s(20)}}{\\alpha \\left[ \\beta \\cdot \\rho \\cdot C_{sm(T)} - C_L \\right] \\cdot 1.024^{(T-20)}}","symbols":[{"s":"C_s(20)","d":"20℃清水饱和溶解氧","u":"9.17 mg/L"},{"s":"α、β","d":"污水/清水转移系数比、饱和 DO 比","u":"—"},{"s":"C_L","d":"池内控制 DO","u":"1.5～2.0 mg/L"}],"range":"α 0.6～0.95；β 0.90～0.97","note":"α/β 为存疑参数，应采用厂家实测数据"},{"code":"F-5.7","name":"氧转移效率与鼓风量","expr":"G_s = \\dfrac{SOR}{0.28 \\cdot E_A}","symbols":[{"s":"0.28","d":"20℃空气含氧量","u":"kgO₂/m³"},{"s":"E_A","d":"氧转移效率","u":"小数"},{"s":"G_s","d":"鼓风量","u":"m³/h"}],"range":"微孔曝气清水 OTE 15%～35%（水深 4～6 m）","note":"实际污水 OTE = α×清水 OTE"},{"code":"F-5.11","name":"硝化碱度消耗与剩余碱度校核","expr":"ALK_{剩余} = ALK_{进水} - 7.14\\, \\Delta NH_3\\text{-}N_{硝化} + 3.57\\, \\Delta NO_3\\text{-}N_{反硝化}","symbols":[{"s":"7.14","d":"硝化耗碱（2×50/14）","u":"gCaCO₃/gNH₃-N"},{"s":"3.57","d":"反硝化产碱（50/14）","u":"gCaCO₃/gNO₃-N"}],"range":"进水碱度 150～300 mg/L；剩余碱度 ≥50～100 mg/L","note":"低碱度+高氨氮须初设阶段校核"},{"code":"F-5.12","name":"需氧量快速估算","expr":"AOR \\approx Q \\times (S_0 - S_e) \\times 10^{-3} \\times k_{O_2}","symbols":[{"s":"k_O2","d":"综合需氧系数","u":"kgO₂/kgBOD₅"}],"range":"0.8～1.1（碳氧化）；1.3～1.8（硝化脱氮）","note":"与详算偏差宜 <10%，方案阶段用"}]},{"id":6,"title_zh":"化学除磷与加药","formulas":[{"code":"F-6.1","name":"金属盐除磷摩尔比","expr":"\\beta = \\dfrac{n_{Al\\ or\\ Fe}}{n_P}","symbols":[{"s":"β","d":"金属/磷摩尔比","u":"mol/mol"}],"range":"同步沉淀 1.5～3.0；后置沉淀 2～4","note":"理论计量 β=1；实际以烧杯试验修正"},{"code":"F-6.2","name":"铝盐/铁盐投加量换算","expr":"D = \\beta \\times \\dfrac{\\Delta P}{31} \\times \\dfrac{M_{药剂}}{n_{Me}}","symbols":[{"s":"ΔP","d":"化学去除磷量","u":"mg/L"},{"s":"M_药剂","d":"药剂摩尔质量","u":"g/mol"},{"s":"n_Me","d":"每摩尔药剂金属摩尔数","u":"—"}],"range":"18 水硫酸铝 ×10.74；6 水三氯化铁 ×8.72","note":"商品药剂按有效 Al/Fe 含量折算"},{"code":"F-6.4","name":"混凝沉淀投加量","expr":"D = d \\cdot Q","symbols":[{"s":"d","d":"投加量","u":"mg/L"},{"s":"Q","d":"流量","u":"10³ m³/d"},{"s":"D","d":"药剂投加量","u":"kg/d"}],"range":"PAC 10～50 mg/L；FeCl₃ 20～80 mg/L；PAM 0.1～0.5 mg/L","note":"高效沉淀池表面负荷 8～20 m/h"},{"code":"F-6.5","name":"反硝化外加碳源需求量","expr":"COD_{需求} = 2.86 \\times \\Delta NO_3\\text{-}N;\\quad CH_3OH = 2.47\\,NO_3\\text{-}N + 1.53\\,NO_2\\text{-}N + 0.87\\,DO","symbols":[{"s":"2.86","d":"理论碳源需求（40/14）","u":"gCOD/gNO₃-N"}],"range":"理论 2.86；实用 3.5～5 gCOD/gNO₃-N","note":"按出水 NO₃-N 在线反馈投加防过量"},{"code":"F-6.6","name":"碳源 COD 当量换算","expr":"COD_{eq} = \\dfrac{z \\times 32}{M}","symbols":[{"s":"z","d":"完全氧化需 O₂ 摩尔数","u":"mol/mol"},{"s":"M","d":"物质摩尔质量","u":"g/mol"}],"range":"甲醇 1.50；乙酸 1.07；乙酸钠 0.78；葡萄糖 1.07 gCOD/g","note":"复合碳源按厂家标定 COD 值"},{"code":"F-6.9","name":"pH 调节与碱度药剂换算","expr":"1\\ \\mathrm{mg/L}\\ 碱度(CaCO_3) \\equiv 0.80\\ NaOH \\equiv 1.06\\ Na_2CO_3 \\equiv 0.74\\ Ca(OH)_2 \\equiv 0.56\\ CaO","symbols":[{"s":"ALK","d":"碱度（以 CaCO₃ 计）","u":"mg/L"}],"range":"按 F-5.11 碱度缺口投加","note":"Na₂CO₃ 缓冲性好；石灰价廉但泥量大"}]},{"id":7,"title_zh":"脱氮计算","formulas":[{"code":"F-7.1","name":"硝化最低污泥龄","expr":"\\dfrac{1}{\\theta_c^{min}} = \\mu_n - b_n","symbols":[{"s":"μ_n","d":"硝化菌比增长速率","u":"d⁻¹"},{"s":"b_n","d":"硝化菌内源衰减系数","u":"d⁻¹"}],"range":"20℃ 时 1.5～3 d；10℃ 时 4～8 d","note":"低于 θ_c^min 硝化菌洗出"},{"code":"F-7.2","name":"硝化速率温度/基质/DO 修正","expr":"\\mu_n = 0.47 \\cdot e^{0.098(T-15)} \\cdot \\dfrac{N}{K_N + N} \\cdot \\dfrac{DO}{K_O + DO};\\quad K_N = 10^{0.051T-1.158}","symbols":[{"s":"N","d":"氨氮浓度","u":"mg/L"},{"s":"K_O","d":"氧半饱和常数","u":"取 1.3 mg/L"}],"range":"20℃、DO=2 时 μ_n≈0.6～0.8 d⁻¹","note":"0.47 系数基于 pH≈7.2，存疑参数"},{"code":"F-7.3","name":"硝化设计污泥龄","expr":"\\theta_c^{design} = SF \\cdot \\theta_c^{min}","symbols":[{"s":"SF","d":"安全系数","u":"2.0～2.5"}],"range":"南方 10～15 d；北方 15～25 d（按最不利水温）","note":"生物除磷并存时 θ_c 不宜超 25 d"},{"code":"F-7.5","name":"反硝化速率与缺氧区容积","expr":"V_{anox} = \\dfrac{N_{去除}}{q_{DNR} \\cdot X_v};\\quad q_{DNR,T} = q_{DNR,20} \\cdot 1.08^{(T-20)}","symbols":[{"s":"q_DNR","d":"反硝化速率","u":"kgNO₃-N/(kgMLVSS·d)"},{"s":"X_v","d":"MLVSS","u":"kg/m³"}],"range":"内碳源 0.01～0.04；外加碳源 0.1～0.3","note":"低碳源污水取低值并做中试"},{"code":"F-7.6","name":"内回流比与总氮去除率","expr":"\\eta_{TN} = \\dfrac{R_i + R}{1 + R_i + R}","symbols":[{"s":"R_i","d":"硝化液内回流比","u":"—"},{"s":"R","d":"污泥回流比","u":"—"}],"range":"R_i 100%～400%；R_i=300%、R=100% 时 η 上限 80%","note":"假设进水硝态氮为 0、反硝化完全；不宜超 400%～500%"},{"code":"F-7.9","name":"脱氮碳源校核","expr":"COD_{可用} \\geq 2.86 \\times \\Delta NO_3\\text{-}N \\times k_s;\\quad \\dfrac{BOD_5}{TN} \\geq 4","symbols":[{"s":"k_s","d":"合成修正系数","u":"1.2～1.7"}],"range":"不足时外加碳源或低碳工艺","note":"联动 F-6.5、F-6.6"},{"code":"F-7.10","name":"氮形态平衡与达标极限","expr":"TKN = 有机氮 + NH_3\\text{-}N;\\quad 同化氮 = 0.12 \\cdot \\Delta X_v;\\quad TN_e = NH_3\\text{-}N_e + NO_3\\text{-}N_e + N_{org,e}","symbols":[{"s":"ΔX_v","d":"挥发性剩余污泥产量","u":"kgVSS/d"},{"s":"N_org,e","d":"出水有机氮（含 rDON）","u":"mg/L"}],"range":"rDON 0.5～1.5 mg/L 构成 TN≤10 极限约束","note":"准四类需后置反硝化滤池"}]},{"id":8,"title_zh":"二沉池与沉淀","formulas":[{"code":"F-8.1","name":"表面负荷（溢流率）","expr":"q = \\dfrac{Q}{A}","symbols":[{"s":"Q","d":"流量","u":"m³/h"},{"s":"A","d":"池表面积","u":"m²"},{"s":"q","d":"表面负荷","u":"m/h"}],"range":"初沉池 1.5～3.0；二沉池 0.6～1.5；高效沉淀池 8～20","note":"二沉池按最高时流量设计"},{"code":"F-8.2","name":"沉淀时间","expr":"t = \\dfrac{V}{Q} = \\dfrac{H}{q}","symbols":[{"s":"H","d":"有效水深","u":"m"}],"range":"初沉池 1.0～2.0 h；二沉池 1.5～4.0 h","note":"有效水深初沉 2.5～4.0 m、二沉 3.0～4.5 m"},{"code":"F-8.3","name":"二沉池固体负荷","expr":"G = \\dfrac{Q(1+R)X}{A}","symbols":[{"s":"R","d":"污泥回流比","u":"—"},{"s":"X","d":"MLSS","u":"kg/m³"},{"s":"G","d":"固体负荷","u":"kg/(m²·d)"}],"range":"≤150 kg/(m²·d)","note":"与表面负荷双控；高 MLSS 工况常起控制作用"},{"code":"F-8.4","name":"出水堰负荷","expr":"q_w = \\dfrac{Q}{L_w}","symbols":[{"s":"L_w","d":"堰长","u":"m"},{"s":"q_w","d":"堰负荷","u":"L/(s·m)"}],"range":"二沉池 ≤1.7；初沉池 ≤2.9 L/(s·m)","note":"大池径采用双侧堰或出水槽"},{"code":"F-8.6","name":"Stokes 沉速","expr":"u = \\dfrac{g(\\rho_s - \\rho) d^2}{18\\mu}","symbols":[{"s":"ρ_s、ρ","d":"颗粒与水的密度","u":"kg/m³"},{"s":"d","d":"粒径","u":"m"},{"s":"μ","d":"动力黏度","u":"Pa·s"}],"range":"适用 Re<1；0.2 mm 砂粒过渡区修正后约 18～24 mm/s","note":"沉砂池按 u₀ 15～30 mm/s 设计"},{"code":"F-8.7","name":"固体通量理论（Coe-Clevenger）","expr":"G = vX + u_b X;\\quad G_L = \\dfrac{u_i C_i}{1 - C_i/C_u};\\quad A = \\dfrac{Q_0 C_0}{G_L}","symbols":[{"s":"G_L","d":"极限固体通量","u":"kg/(m²·h)"},{"s":"C_u","d":"底流浓度","u":"kg/m³"}],"range":"SVI>150 时 G_L 显著下降","note":"二沉池校核与浓缩池设计共用"}]},{"id":9,"title_zh":"污泥处理","formulas":[{"code":"F-9.1","name":"剩余污泥产量（动力学法）","expr":"\\Delta X_v = \\dfrac{Y \\cdot Q(S_0 - S_e)}{1 + K_d \\theta_c} \\times 10^{-3}","symbols":[{"s":"Y_obs","d":"表观产率 Y/(1+K_d·θ_c)","u":"kgVSS/kgBOD₅"},{"s":"ΔX_v","d":"挥发性剩余污泥产量","u":"kgVSS/d"}],"range":"Y_obs 0.4～0.6（SRT 5～15 d）","note":"仅挥发性部分，总量见 F-9.2"},{"code":"F-9.2","name":"总污泥产量（规范式）","expr":"\\Delta X = \\dfrac{Y Q(S_0-S_e)}{1+K_d \\theta_c} \\times 10^{-3} + f \\cdot Q(SS_0 - SS_e) \\times 10^{-3} - Q \\cdot X_e \\times 10^{-3}","symbols":[{"s":"f","d":"进水 SS 惰性固体转换率","u":"0.5～0.7"},{"s":"X_e","d":"出水 SS","u":"mg/L"}],"range":"市政厂 0.6～0.9 kgDS/kgBOD₅ 去除","note":"化学除磷污泥另加 MePO₄ 与金属氢氧化物"},{"code":"F-9.3","name":"含水率—体积换算","expr":"V_2 = V_1 \\cdot \\dfrac{100 - P_1}{100 - P_2}","symbols":[{"s":"P","d":"含水率","u":"%"},{"s":"V","d":"污泥体积","u":"m³"}],"range":"1000 kg DS：99%→100 m³；97%→33.3 m³；80%→5 m³","note":"密度近似 1；浓缩脱水逐级核算"},{"code":"F-9.8","name":"厌氧消化池容积","expr":"V = Q_s \\cdot \\theta;\\quad V = \\dfrac{W_{VS}}{L_v}","symbols":[{"s":"θ","d":"固体停留时间 SRT","u":"d"},{"s":"L_v","d":"容积负荷","u":"kgVS/(m³·d)"}],"range":"中温 SRT 20～30 d；L_v 0.5～1.6（高含固 2.0～3.5）","note":"SRT<10 d 产甲烷菌洗出风险大"},{"code":"F-9.9","name":"VS 降解率与消化后固体量","expr":"W_{out} = W_{in} \\left(1 - f_{VS} \\cdot \\eta_{VS}\\right);\\quad \\eta_{VS} = \\dfrac{f_{in} - f_{out}}{f_{in}(1 - f_{out})}\\ \\text{（Van Kleeck）}","symbols":[{"s":"f_VS","d":"进泥 VS/TS 比","u":"—"},{"s":"η_VS","d":"VS 降解率","u":"%"}],"range":"混合污泥 40%～55%（中温、SRT 20～30 d）","note":"GB 18918 要求有机物降解率 >40%"},{"code":"F-9.10","name":"沼气产量与成分","expr":"G = \\eta_{VS} \\cdot W_{VS} \\times g;\\quad G_{CH_4} = 0.35 \\times COD_{去除}","symbols":[{"s":"g","d":"沼气产率","u":"0.75～1.10 Nm³/kgVS 去除"},{"s":"0.35","d":"理论甲烷产量","u":"m³CH₄/kgCOD"}],"range":"甲烷含量 55%～70%；热值 21～25 MJ/m³","note":"产率按 T/CECS 496-2017 复核"},{"code":"F-9.14","name":"泥饼产量与固相回收率","expr":"W_{cake} = \\dfrac{W_{DS} \\cdot R_s}{1 - P_{cake}};\\quad R_s = \\dfrac{C_k(C_0 - C_e)}{C_0(C_k - C_e)} \\times 100\\%","symbols":[{"s":"C_0、C_k、C_e","d":"进泥/泥饼/滤液含固率","u":"%"},{"s":"R_s","d":"固相回收率","u":"%"}],"range":"R_s≥95%；泥饼含水率带式 75～82%、离心 68～80%、板框 50～65%","note":"滤液回流负荷计入全厂平衡"},{"code":"F-9.16","name":"干化蒸发水量","expr":"W_{evap} = W_{DS} \\left( \\dfrac{1}{1-P_1} - \\dfrac{1}{1-P_2} \\right)","symbols":[{"s":"P_1、P_2","d":"干化前后含水率","u":"小数"},{"s":"W_evap","d":"蒸发水量","u":"t 水/tDS"}],"range":"80%→40%：3.33 t/tDS；80%→10%：3.89 t/tDS","note":"干化线按蒸发水量定规格"}]},{"id":10,"title_zh":"消毒与其他","formulas":[{"code":"F-10.1","name":"加氯量","expr":"D_{Cl_2} = a \\cdot Q","symbols":[{"s":"a","d":"加氯量","u":"mg/L"},{"s":"Q","d":"流量","u":"10³ m³/d"}],"range":"二级出水 5～15 mg/L；再生水 8～15 mg/L","note":"按最高时流量配置加氯机"},{"code":"F-10.2","name":"折点氯化需氯量","expr":"Cl_2 : NH_3\\text{-}N = 7.6 : 1\\ \\text{（质量比）}","symbols":[{"s":"Cl_2","d":"理论折点需氯量","u":"mg/L"}],"range":"市政二级出水通常控制折点前","note":"实际需氯量 = 投加量 − 接触后余氯"},{"code":"F-10.3","name":"CT 值设计","expr":"CT = C_{余} \\times T_{10}","symbols":[{"s":"C_余","d":"消毒剂残余浓度","u":"mg/L"},{"s":"T_10","d":"示踪实际停留时间","u":"min"}],"range":"粪大肠菌群达标 CT 450～2000 mg·min/L","note":"T₁₀ 取 0.6～0.9θ"},{"code":"F-10.4","name":"氯接触池容积","expr":"V = Q_{max} \\cdot T","symbols":[{"s":"T","d":"接触时间","u":"min"}],"range":"T≥30 min；廊道长宽比 ≥10（宜 20～50）","note":"廊道设导流墙避免短流"},{"code":"F-10.5","name":"紫外线（UV）剂量","expr":"D_{UV} = I \\cdot t","symbols":[{"s":"I","d":"平均紫外强度","u":"mW/cm²"},{"s":"t","d":"照射时间","u":"s"}],"range":"二级出水 20～40 mJ/cm²（一级 A 常取 25～30）","note":"按灯管老化×套管结垢系数折减"}]}]};
